<template><view class="screen"><Scenery title="各自努力，一起向前。" caption="把一个人的坚持，变成一群人的陪伴。" compact/><AccountGate/><view v-if="store.user"><view><view v-if="!store.room"><view class="card sage"><text class="title">为同伴留一个位置</text><text class="muted">建立属于你们的安静角落。房间最多 12 人，通过邀请码加入。</text><input v-model="name" placeholder="例如：期末冲刺小分队" maxlength="30"/><button class="primary" :disabled="store.busy" @click="act('/rooms/create','POST',{name})">创建自习室</button></view><view class="card"><text class="title">加入同学的自习室</text><input v-model="code" placeholder="输入 10 位邀请码" maxlength="10"/><button class="secondary" :disabled="store.busy" @click="act('/rooms/join','POST',{code})">加入自习室</button></view></view><view v-else><view class="card sage"><text class="title">{{store.room.name}}</text><view class="row between"><text class="muted">{{store.room.members.length}} / {{store.room.capacity}} 位同学</text><text class="pill">{{store.room.members.filter(m=>m.online).length}} 人在线</text></view><view class="invite space" @click="copy"><text class="eyebrow">邀请同伴一起学习</text><text class="invite-code">{{store.room.invite_code}}</text><text class="muted">点击复制邀请码</text></view></view><view class="card"><view class="row between"><text class="title">自习中的伙伴</text><button class="secondary small" @click="sync(true)">刷新</button></view><view class="classroom"><view class="classroom-board"><text class="board-title">小时的安静教室</text><text>今日课题：把眼前的一小步做好</text><view class="chalk-tray"></view></view><view class="classroom-front"><text>讲台</text><text>☀ 窗边的阳光刚刚好</text></view><view class="seats"><view v-for="seat in seats" :key="seat.index" class="seat" :class="{occupied:!!seat.member}"><view class="seat-art"><image v-if="seat.member" class="seat-puppy" src="/static/mascot/xiaoshi.png" mode="aspectFit" alt="小时陪你自习"/><CartoonArt v-else class="seat-desk" kind="desk" label="空闲小书桌"/></view><text class="seat-number">{{seat.index+1}} 号桌</text><text class="seat-name">{{seat.member?seat.member.nickname:'虚位以待'}}</text><text class="seat-state">{{seat.member?(seat.member.online?(seat.member.focus_status==='running'?'专注中':seat.member.focus_status==='paused'?'已暂停':'在线'):'暂时离开'):'空闲位置'}}</text></view></view><text class="classroom-note">座位按成员排列 · 不代表固定选座</text></view><view v-for="member in store.room.members" :key="member.id" class="item"><view class="avatar">{{member.nickname.slice(0,1)}}</view><view class="grow"><text class="item-title">{{member.nickname}}{{member.id===store.user.id?' · 我':''}}</text><text class="muted">{{member.id===store.room.owner_id?'房主':'同学'}} · {{member.online?'在线':'暂时离开'}}</text></view><text class="pill">{{member.focus_status==='running'?'专注中':member.focus_status==='paused'?'已暂停':'准备中'}}</text></view><text class="footnote">共享专注状态与今日累计时长，个人任务和历史明细仅自己可见。</text></view><RoomLeaderboard :room="store.room" :user-id="store.user.id"/><button class="primary" @click="goFocus">开始我的专注 →</button><button class="secondary space" :disabled="store.busy" @click="leave">退出自习室</button></view></view></view></view><AppNav current="rooms"/></template>
<script setup>
import AppNav from '../../components/AppNav.vue';
import RoomLeaderboard from '../../components/RoomLeaderboard.vue';
import CartoonArt from '../../components/CartoonArt.vue';
import {ref,computed} from 'vue';import Scenery from '../../components/Scenery.vue';import {onShow,onHide,onUnload} from '@dcloudio/uni-app';import AccountGate from '../../components/AccountGate.vue';import {store,refresh,act} from '../../services/store';import {request,confirm,message} from '../../services/api';
const pageVisible=ref(false);
const name=ref(''),code=ref('');let interval;let pending=false;let visible=false;
const seats=computed(()=>Array.from({length:store.room?.capacity||12},(_,index)=>({index,member:store.room?.members[index]})));
async function sync(manual=false){if(!store.user||pending)return;pending=true;try{const data=await request('/rooms/current');store.room=data.room;if(manual)message('已更新自习室状态');}catch(error){if(manual)message(error.message||'刷新失败，请稍后重试');}finally{pending=false;}}
onShow(async()=>{visible=true;pageVisible.value=true;clearInterval(interval);await refresh();if(visible)interval=setInterval(()=>sync(),10000);});onHide(()=>{visible=false;pageVisible.value=false;clearInterval(interval);});onUnload(()=>{visible=false;pageVisible.value=false;clearInterval(interval);});
function copy(){uni.setClipboardData({data:store.room.invite_code,showToast:false,success:()=>message('邀请码已复制，发给你的学习搭子吧。'),fail:()=>message('复制未成功，请手动复制邀请码。')});}
function goFocus(){uni.switchTab({url:'/pages/focus/index'});}
async function leave(){if(await confirm('退出后可以凭邀请码重新加入。房主退出后由下一位成员接任，最后一人退出将关闭房间。'))await act('/rooms/leave');}
</script>
<style scoped>.invite{background:#ffffff90;text-align:center;padding:25rpx;border-radius:20rpx}.invite-code{font-size:40rpx;letter-spacing:6rpx;color:#8d734f;font-weight:600}.seats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18rpx;margin:25rpx 0}.seat{background:#fffcf6;border:2rpx dashed #e9dcc1;border-radius:24rpx;text-align:center;padding:22rpx 8rpx;min-width:0}.seat.occupied{background:linear-gradient(145deg,#f7f0e2,#f8ece7);border:2rpx solid #e9dcc1}.seat-icon{width:64rpx;height:64rpx;line-height:64rpx;margin:0 auto 12rpx;background:#ffffffad;border-radius:50%;color:#ab9067;font-size:29rpx}.seat-name{display:block;font-size:23rpx;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#8d734f}.seat-state{display:block;font-size:18rpx;color:#ab9067;margin-top:8rpx}.seat{background:#fffaf0;border-color:#e8ce97}.seat.occupied{background:#ffedb5;border-color:#dfb257}.seat-art{display:flex;justify-content:center;margin:0 auto 12rpx}.seat-desk,.seat-puppy{width:100rpx;height:100rpx}.seat-state{color:#927043}.seat-name{color:#6d4e27}.invite{background:#fffaf0}</style>
<style scoped>.classroom{margin-top:24rpx;border:3rpx solid #dec08c;border-radius:22rpx;background:repeating-linear-gradient(0deg,#f8e9c8 0,#f8e9c8 78rpx,#ecdbb8 80rpx);padding:24rpx 16rpx}.classroom-board{position:relative;margin:0 35rpx 26rpx;background:#6f5e43;color:#fff7dc;border:8rpx solid #c99f62;border-radius:12rpx;text-align:center;padding:28rpx 12rpx;font-size:23rpx;line-height:1.8;box-shadow:0 6rpx 0 #b7915c}.board-title{display:block;font-size:32rpx;font-weight:600}.chalk-tray{position:absolute;bottom:-8rpx;left:15%;width:70%;height:8rpx;background:#e4c28b}.classroom-front{display:flex;justify-content:space-between;font-size:20rpx;color:#94703d;padding:0 16rpx}.seats{gap:22rpx 16rpx}.seat{background:#fff7e1;border:0;border-bottom:8rpx solid #d7b37d;border-radius:12rpx;padding:14rpx 6rpx;box-shadow:0 8rpx 0 #ecd4a4}.seat.occupied{background:#ffe8ae;border:0;border-bottom:8rpx solid #b99152}.seat-number{display:block;color:#a38351;font-size:18rpx;margin-bottom:4rpx}.classroom-note{display:block;text-align:center;font-size:20rpx;color:#947344;margin:24rpx 0 0}.seat-puppy,.seat-desk{width:92rpx;height:92rpx}</style>
